<script setup>
import { ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth';
const driverMobileUrl=import.meta.env.VITE_DRIVER_MOBILE_URL || '/driver/login';
const demoMode=String(import.meta.env.VITE_DEMO_MODE??'true')==='true';const email=ref(demoMode?'owner@demo.com':''),password=ref(demoMode?'Owner123!':''),error=ref(''),loading=ref(false); const auth=useAuthStore(),router=useRouter();
async function submit(){error.value='';loading.value=true;try{await auth.login(email.value,password.value);router.push('/')}catch(e){error.value=e.response?.data?.error||'Unable to sign in'}finally{loading.value=false}}
function useDemo(e,p){email.value=e;password.value=p}
</script>
<template><div class="login"><section class="login-showcase"><div class="brand"><div class="brand-mark">FD</div><div><b>FlowDepot</b><span>Warehouse Operations Suite</span></div></div><div><h1>One operating system for every warehouse movement.</h1><p>Multi-site leasing, utilities billing, tenant inventory, store replenishment, driver dispatch, QR/RFID traceability, incident rectification and paperless records—connected in a single operational workflow.</p></div><p>Owner → Tenant → Warehouse → Delivery → Proof → Record.</p></section><section class="login-panel"><form class="login-card" @submit.prevent="submit"><h2>Welcome back</h2><p>Sign in to the role-based workspace.</p><div class="field"><label for="login-email">Email</label><input id="login-email" v-model="email" type="email" autocomplete="username" required/></div><div class="field" style="margin-top:12px"><label for="login-password">Password</label><input id="login-password" v-model="password" type="password" autocomplete="current-password" required/></div><div v-if="error" class="error">{{error}}</div><button class="btn" style="width:100%;margin-top:18px" :disabled="loading">{{loading?'Signing in…':'Sign in'}}</button><div class="driver-mobile-entry"><b>Driving today?</b><p>Open your routes, scan deliveries, and capture proof of delivery.</p><a class="btn secondary" :href="driverMobileUrl">Open driver mobile app <span aria-hidden="true">→</span></a></div><div v-if="demoMode" class="demo-accounts"><b>Demo accounts</b><br><a href="#" @click.prevent="useDemo('owner@demo.com','Owner123!')">Owner</a> · owner@demo.com / Owner123!<br><a href="#" @click.prevent="useDemo('tenant@demo.com','Tenant123!')">Tenant</a> · tenant@demo.com / Tenant123!<br><a href="#" @click.prevent="useDemo('manager@demo.com','Manager123!')">Manager</a> · manager@demo.com / Manager123!<br><a href="#" @click.prevent="useDemo('driver@demo.com','Driver123!')">Driver</a> · driver@demo.com / Driver123!</div></form></section></div></template>
